import { existsSync, lstatSync, mkdirSync, readFileSync, realpathSync, symlinkSync, writeFileSync, } from "node:fs";
import path from "node:path";
import { loadTemplate } from "../generator/template-engine.js";
// The agent skills `flisk project` writes into a new project, so a coding agent opened there knows how to build and run
// the app with Flisk. Copies of .claude/skills/<name>/SKILL.md, shipped in cli/templates/agent-skills (a test keeps
// them identical).
export const PROJECT_AGENT_SKILLS = [
    "flisk-build",
    "flisk-recipe-starters",
    "flisk-recipe-shop",
    "flisk-recipe-saas",
    "flisk-recipe-ai-agent",
    "flisk-recipe-blog",
    "flisk-doctor",
    "flisk-up",
    "flisk-resource",
    "flisk-tool-add",
    "flisk-status",
    "flisk-troubleshoot",
    "flisk-agent-ops",
    "flisk-convert",
];
// Claude Code reads .claude/skills; Codex, Cursor and other agents read .agents/skills.
export const CLAUDE_SKILLS_DIR = ".claude/skills";
export const AGENTS_SKILLS_DIR = ".agents/skills";
export const AGENT_SKILL_DIRS = [CLAUDE_SKILLS_DIR, AGENTS_SKILLS_DIR];
const DOCS_URL = "https://github.com/flisk-sh/flisk-cli/blob/main/docs/";
export const PROJECT_AGENTS_MD = `# AGENTS.md

This project runs on [Flisk](https://github.com/flisk-sh/flisk-cli). To build or run something here, follow the Flisk skills in \`.agents/skills\` (Claude Code: \`.claude/skills\`), starting with \`flisk-build\`.

- Add a service: \`flisk resource <name> --type <frontend|backend|worker|agent|mcp> --stack <stack> --yes\`
- Start it: \`flisk up <stack>\`, then \`flisk status --json\`: every resource must be \`ready\`; request \`<url or directUrl>/health\` of each
- When something fails: \`flisk doctor\`, then \`flisk logs -s <service>\`
- Do not hand-write Dockerfiles, Compose files or Tiltfiles. Do not edit the files Flisk generates (\`.autogenerated/\` folders, \`.flisk/.flisk-out/\`, \`Tiltfile\`, \`TILT_*.star\`, \`.tiltignore\`): \`flisk up\` writes them again. Change \`service.json\` instead; \`flisk config explain <file>\` says where a file comes from.

## Working with several agents

- Give each agent its own git worktree (\`git worktree add ../<project>-<agent>\`), so two agents never edit the same checkout.
- Install [Run My Agents](https://github.com/flisk-sh/run-my-agents) (\`/plugin marketplace add flisk-sh/run-my-agents\`, then \`/plugin install run-my-agents@run-my-agents\`): it stops an edit once when another agent changed the same file in the last few minutes.
- Run \`flisk status --json\` before starting a stack, so an agent sees what is already running.
`;
// Claude Code reads CLAUDE.md, other agents read AGENTS.md: one line makes them the same file.
export const PROJECT_CLAUDE_MD = "@AGENTS.md\n";
export const CI_WORKFLOW = ".github/workflows/flisk.yml";
// A Claude Code hook that blocks Edit and Write on the files Flisk generates (other agents only have AGENTS.md).
export const GENERATED_GUARD_HOOK = ".claude/hooks/flisk-generated-guard.mjs";
export const PROJECT_CLAUDE_SETTINGS = `${JSON.stringify({
    // Defaults for a coding agent in this project: it cannot read env files (they hold generated secrets), asks before
    // pushing, and runs the read-only Flisk checks without prompting. Edit freely; Flisk never overwrites this file.
    permissions: {
        allow: [
            "Bash(flisk status:*)",
            "Bash(flisk doctor:*)",
            "Bash(flisk config verify:*)",
            "mcp__flisk__status",
            "mcp__flisk__doctor",
            "mcp__flisk__config_verify",
            "mcp__flisk__resource_list",
            "mcp__flisk__stack_list",
            "mcp__flisk__network_list",
            "mcp__flisk__logs",
        ],
        ask: ["Bash(git push:*)"],
        deny: ["Read(**/.env)", "Read(**/.env.*)"],
    },
    hooks: {
        PreToolUse: [
            {
                matcher: "Edit|MultiEdit|Write|NotebookEdit",
                hooks: [
                    { type: "command", command: `node "$CLAUDE_PROJECT_DIR/${GENERATED_GUARD_HOOK}"` },
                ],
            },
        ],
    },
}, null, 2)}\n`;
const CLAUDE_SETTINGS = ".claude/settings.json";
/** A command that runs the guard script with node, not one that only mentions its path (for example `echo`). */
function invokesGeneratedGuard(command) {
    const script = GENERATED_GUARD_HOOK.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp(`^\\s*node\\s+["']?[^\\s"']*${script}["']?\\s*$`).test(command);
}
/** A matcher that fires for file edits: absent, empty, `*`, or an alternation naming both Edit and Write. */
function matcherCoversEdits(matcher) {
    if (matcher === undefined || matcher === "" || matcher === "*")
        return true;
    if (typeof matcher !== "string")
        return false;
    const names = matcher.split("|").map((name) => name.trim());
    return names.includes("Edit") && names.includes("Write");
}
function runsGeneratedGuardHook(group) {
    const { hooks, matcher } = (group ?? {});
    return (matcherCoversEdits(matcher) &&
        Array.isArray(hooks) &&
        hooks.some((hook) => {
            const command = hook?.command;
            return typeof command === "string" && invokesGeneratedGuard(command);
        }));
}
/** True when an existing `.claude/settings.json` already runs Flisk's generated-file guard (#5425). */
export function claudeGuardHookWired(projectRoot) {
    try {
        const settings = JSON.parse(readFileSync(path.join(projectRoot, CLAUDE_SETTINGS), "utf-8"));
        const groups = settings?.hooks?.PreToolUse;
        return Array.isArray(groups) && groups.some(runsGeneratedGuardHook);
    }
    catch {
        return false;
    }
}
/** An existing settings file that does not wire the guard: Flisk must not leave a hook script behind (#5425). */
export function claudeGuardHookNeedsWiring(projectRoot) {
    return existsSync(path.join(projectRoot, CLAUDE_SETTINGS)) && !claudeGuardHookWired(projectRoot);
}
/** A hook left by an older Flisk version that no settings file runs, for project, verify and doctor to report (#5425). */
export function claudeGuardHookIsOrphaned(projectRoot) {
    return (existsSync(path.join(projectRoot, GENERATED_GUARD_HOOK)) && !claudeGuardHookWired(projectRoot));
}
// In the repository the skills link to docs/ with relative paths; in a user's project those point nowhere.
export function rewriteSkillLinks(markdown) {
    return markdown.replace(/\]\((?:\.\.\/)+docs\//g, `](${DOCS_URL}`);
}
/** The skill files Flisk ships for the given skill directories: a root-relative path and its contents. */
export function agentSkillFiles(dirs = AGENT_SKILL_DIRS) {
    const files = [];
    for (const name of PROJECT_AGENT_SKILLS) {
        const contents = rewriteSkillLinks(loadTemplate(`agent-skills/${name}/SKILL.md`));
        for (const dir of dirs) {
            files.push({ rel: path.join(dir, name, "SKILL.md"), contents });
        }
    }
    return files;
}
/** Write the skill files for one skill directory. A file that already exists is left alone. */
function writeSkillFiles(projectRoot, dir, written) {
    for (const { rel, contents } of agentSkillFiles([dir])) {
        const target = path.join(projectRoot, rel);
        if (existsSync(target))
            continue;
        mkdirSync(path.dirname(target), { recursive: true });
        writeFileSync(target, contents);
        written.push(rel);
    }
}
/**
 * Make .claude/skills a relative symlink to .agents/skills, so a project keeps one copy of the skills instead of two
 * that can drift apart (#5386). Returns false and changes nothing when .claude/skills already exists (a user's own
 * folder or link) when .claude is itself a link to another folder, or when the filesystem cannot create symlinks (Windows without developer mode, some network drives).
 */
function linkClaudeSkillsToAgentSkills(projectRoot) {
    const link = path.join(projectRoot, CLAUDE_SKILLS_DIR);
    try {
        lstatSync(link);
        return false; // Something is already there: it is not ours to replace.
    }
    catch {
        // Nothing at that path yet, so a link can be created.
    }
    try {
        const parent = path.dirname(link);
        mkdirSync(parent, { recursive: true });
        // A redirected .claude (itself a link) would resolve the relative target from the wrong folder: copy instead.
        if (realpathSync(parent) !== path.join(realpathSync(projectRoot), path.basename(parent)))
            return false;
        // The target is relative to the folder that holds the link: .claude/ -> ../.agents/skills
        symlinkSync(path.join("..", AGENTS_SKILLS_DIR), link, "dir");
        return true;
    }
    catch {
        return false;
    }
}
/**
 * Write the Flisk agent skills and an AGENTS.md into a project. Never overwrites: a file that already exists is left
 * as it is, so a user's own edits survive `flisk project` running again. The skills are written once into
 * .agents/skills, and .claude/skills links to them; where a link cannot be made, .claude/skills gets its own copy.
 * Returns the paths written, relative to the project root.
 */
export function installAgentSkills(projectRoot, options = {}) {
    const written = [];
    writeSkillFiles(projectRoot, AGENTS_SKILLS_DIR, written);
    if (linkClaudeSkillsToAgentSkills(projectRoot)) {
        written.push(CLAUDE_SKILLS_DIR);
    }
    else {
        writeSkillFiles(projectRoot, CLAUDE_SKILLS_DIR, written);
    }
    // The guard hook and the settings that run it are one feature. An existing .claude/settings.json is the user's:
    // never overwrite it, and do not leave a hook script nothing runs (#5425).
    const extras = [];
    if (!claudeGuardHookNeedsWiring(projectRoot)) {
        extras.push([GENERATED_GUARD_HOOK, loadTemplate("agent-hooks/flisk-generated-guard.mjs")]);
    }
    extras.push([CLAUDE_SETTINGS, PROJECT_CLAUDE_SETTINGS], [CI_WORKFLOW, loadTemplate("agent-workflows/flisk.yml")], ["CLAUDE.md", PROJECT_CLAUDE_MD]);
    for (const [rel, contents] of extras) {
        if (rel === CI_WORKFLOW && options.ciWorkflow === false)
            continue;
        const target = path.join(projectRoot, rel);
        if (existsSync(target))
            continue;
        mkdirSync(path.dirname(target), { recursive: true });
        writeFileSync(target, contents);
        written.push(rel);
    }
    const agentsMd = path.join(projectRoot, "AGENTS.md");
    if (!existsSync(agentsMd)) {
        writeFileSync(agentsMd, PROJECT_AGENTS_MD);
        written.push("AGENTS.md");
    }
    return written;
}
